async function ensureBitmapDataUrl(src){
  if(!src) return null;
  if(/^data:image\//i.test(String(src))) return String(src);
  const r = await fetchBitmapSource(src,{provider:$('#provider').value,base:baseURL(),key:$('#key').value.trim()});
  if(!r.ok) throw new Error('Reference image could not be read');
  return fileToDataURI(await r.blob());
}

